body:
FEATURE SPEC: Keyboard navigation for graph canvas

Filed by: GD (WCAG 2.1.1 Keyboard, 2.1.2 No Keyboard Trap)
To: GA

WHY
Canvas elements are click-only by default. Keyboard-only users (including ADHD students using Tab-based
navigation) cannot place points on the graph. This is a WCAG 2.1.1 (Level A) failure.

Current graph questions: retake-practice-5, retake-practice-7 (and any exam with 'graph' in questions.json).

DESIGN

Keyboard model: virtual cursor on canvas. Arrow keys move cursor. Enter places/removes point.

STEP 1: Make canvas focusable
In renderGraph(), add tabindex and aria attributes:
  html += '<canvas id="' + g.canvas_id + '" width="500" height="500"';
  html += ' tabindex="0"';
  html += ' role="application"';
  html += ' aria-label="Interactive graph. Use arrow keys to move cursor, Enter to place point, Delete to remove."';
  html += '></canvas>';

STEP 2: Track keyboard cursor in graphData
In initGraph(), add cursor state to graphData[canvasId]:
  graphData[canvasId].kbCursor = { x: 0, y: 0 };  // graph coordinates

STEP 3: Draw cursor when canvas is focused
Add a drawKbCursor(canvasId) function called from redrawGraph():
  function drawKbCursor(canvasId) {
    var d = graphData[canvasId];
    if (d.kbFocused) {
      var sx = d.ml + ((d.kbCursor.x + 16) / 32) * d.pw;
      var sy = d.mt + ((-d.kbCursor.y + 16) / 32) * d.ph;
      d.ctx.beginPath();
      d.ctx.arc(sx, sy, 8, 0, 2 * Math.PI);
      d.ctx.strokeStyle = '#4A90D9';
      d.ctx.lineWidth = 2;
      d.ctx.setLineDash([4, 2]);
      d.ctx.stroke();
      d.ctx.setLineDash([]);
    }
  }

STEP 4: Keyboard event handler in initGraph()
  canvas.addEventListener('focus', function() {
    graphData[canvasId].kbFocused = true;
    redrawGraph(canvasId);
    updateGraphCounter(canvasId);  // shows cursor position
  });
  canvas.addEventListener('blur', function() {
    graphData[canvasId].kbFocused = false;
    redrawGraph(canvasId);
  });
  canvas.addEventListener('keydown', function(e) {
    var d = graphData[canvasId];
    var step = e.shiftKey ? 0.25 : 1;  // Shift = fine control
    var moved = false;
    if (e.key === 'ArrowRight') { d.kbCursor.x = Math.min(d.kbCursor.x + step, 15); moved = true; }
    if (e.key === 'ArrowLeft')  { d.kbCursor.x = Math.max(d.kbCursor.x - step, -15); moved = true; }
    if (e.key === 'ArrowUp')    { d.kbCursor.y = Math.min(d.kbCursor.y + step, 15); moved = true; }
    if (e.key === 'ArrowDown')  { d.kbCursor.y = Math.max(d.kbCursor.y - step, -15); moved = true; }
    if (moved) {
      e.preventDefault();  // prevent page scroll
      redrawGraph(canvasId);
      updateGraphCounter(canvasId);
      return;
    }
    // Place or remove point at cursor
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      // Simulate a click at cursor position
      var sx = d.kbCursor.x;
      var sy = d.kbCursor.y;
      // Asymptote mode: place asymptote at cursor
      if (d.asymptoteMode === 'vertical') {
        d.asymptotes.vertical = [sx];
        d.asymptoteMode = null;
        var vb = document.getElementById('vaBtn-' + canvasId);
        if (vb) vb.classList.remove('active');
        updateGraphCounter(canvasId); redrawGraph(canvasId); return;
      }
      if (d.asymptoteMode === 'horizontal') {
        d.asymptotes.horizontal = [sy];
        d.asymptoteMode = null;
        var hb = document.getElementById('haBtn-' + canvasId);
        if (hb) hb.classList.remove('active');
        updateGraphCounter(canvasId); redrawGraph(canvasId); return;
      }
      // Remove if near existing point (same logic as click handler)
      for (var i = d.points.length - 1; i >= 0; i--) {
        if (Math.abs(d.points[i].gx - sx) < 0.5 && Math.abs(d.points[i].gy - sy) < 0.5) {
          d.points.splice(i, 1);
          updateGraphCounter(canvasId); redrawGraph(canvasId); return;
        }
      }
      // Place point
      var screenX = d.ml + ((sx + 16) / 32) * d.pw;
      var screenY = d.mt + ((-sy + 16) / 32) * d.ph;
      d.points.push({ x: screenX, y: screenY, gx: sx, gy: sy, status: null });
      updateGraphCounter(canvasId);
      redrawGraph(canvasId);
    }
    // Remove last point with Delete/Backspace
    if (e.key === 'Delete' || e.key === 'Backspace') {
      e.preventDefault();
      if (d.points.length > 0) {
        d.points.pop();
        updateGraphCounter(canvasId); redrawGraph(canvasId);
      }
    }
  });

STEP 5: Update graph counter to show cursor position when keyboard-focused
In updateGraphCounter(), add:
  if (d.kbFocused) {
    text += ' | cursor: (' + d.kbCursor.x + ', ' + d.kbCursor.y + ')';
  }

STEP 6: Announce state to screen reader
When a point is placed, update an off-screen live region:
  var liveRegion = document.getElementById('graphLiveRegion');
  if (!liveRegion) {
    liveRegion = document.createElement('div');
    liveRegion.id = 'graphLiveRegion';
    liveRegion.setAttribute('aria-live', 'polite');
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.className = 'sr-only';
    document.body.appendChild(liveRegion);
  }
  liveRegion.textContent = 'Point placed at (' + sx + ', ' + sy + '). ' + d.points.length + ' points total.';

KEYBOARD MAP (document in graph counter or tooltip for sighted keyboard users):
  Arrow keys: move cursor 1 unit
  Shift+Arrow: move cursor 0.25 units (fine)
  Enter / Space: place or remove point at cursor
  Delete / Backspace: remove last point placed

ACCEPT CRITERIA
[x] Canvas receives focus via Tab key (tabindex=0)
[x] Focused canvas shows dashed blue cursor ring at current cursor position
[x] Arrow keys move cursor without scrolling page
[x] Enter/Space places point at cursor (same logic as click)
[x] Enter/Space near existing point removes it
[x] Delete/Backspace removes last point
[x] Asymptote mode works with Enter: press VA button, then use keyboard to position, Enter to confirm
[x] Screen reader announces point placement via aria-live region
[x] Cursor position shown in graph counter when keyboard-focused
[x] Cursor ring disappears on blur
[x] Mouse click continues to work (keyboard does not break mouse)
[x] CHECK GRAPH button still works after keyboard placement

SCOPE: exam.html initGraph() and renderGraph() only.
